entity Prob_5_55_vhdl is	port (x_in, clk, reset_b: in bit; y: out bit);end Prob_5_55_vhdl;architecture Behavioral of Prob_5_55_vhdl is	constant s0: bit_vector (1 downto 0)  := "00";	constant s1: bit_vector (1 downto 0)  := "01";	constant s2: bit_vector (1 downto 0)  := "10";	constant s3: bit_vector (1 downto 0)  := "11";	signal state, next_state: bit_vector (1 downto 0);begin	process (clk, reset_b) begin		if (reset_b = '0') then state <= s0; 		elsif clk'event and clk = '1' then state <= next_state; end if;	end process;
		process ( clk, reset_b) begin		y <= '0';		next_state <= s0;	case (state) is			when s0 =>			 y <= '0'; if (x_in = '1') then next_state <= s1; else next_state <= s0; end if; 					when s1 =>			 y <= '0'; if (x_in = '1') then next_state <= s2; else next_state <= s1; end if; 					when s2 =>			 y <= '0'; if (x_in = '1') then next_state <= s3; else next_state <= s2; end if; 					when s3 =>			 y <= '0'; if (x_in = '1') then next_state <= s1; else next_state <= s3; end if; 					when others =>	 y <= '0'; next_state <= s0; 	end case;	end process;end Behavioral;